package main

import (
	"fmt"
	"io"
	"os"
	"sort"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, t := nextInt(), nextInt()
	a := make([]int, n)
	for i := range a {
		a[i] = nextInt()
	}
	sort.Ints(a)
	answer := 0
	for i := 0; i < n; {
		j := i
		for j < n && a[j] == a[i] {
			j++
		}
		v := a[i]
		b := t - v
		if v <= b {
			k := sort.SearchInts(a, b)
			if k < n && a[k] == b && (v != b || j-i >= 2) {
				answer++
			}
		}
		i = j
	}
	fmt.Println(answer)
}
